520-     * A steward transfers the person to another sheet by its id; not a retired person, not to this sheet
521-     * nor to an archived one (an id never used starts that sheet, as loading it would; a refused transfer
522-     * leaves it unstarted), and not when their contact is, as compared, already on the other sheet. They
523-     * arrive with every grade (and its from-date), their terms, contact, aliases and holds, and their claims
524-     * ({@link ClaimService#receive}) and their statements; their patron links either way, pool memberships and
525-     * watchers are dropped, and they leave this sheet. When a person on the other sheet has, as names are
526-     * compared, their name or an alias, they are merged into that person there, as {@link #merge} does
527-     * (their contact then no bar); refused when that person is retired, or when their names are those of
528-     * more than one person there. Each sheet audits the transfer, the other sheet then the merge, each
529-     * followed by its rollup lines.
530-     */
531-    @Transactional
532:    public void transfer(String sheetId, String user, Long id, String toSheetId) {
533-        if (sheetId.equals(toSheetId)) throw new PersonTransferRefusedException();
534-        if (sheets.existsById(sheetId)) sheetService.load(toSheetId, user.strip());
535-        // lock both sheets, always in the same order, so two transfers between them cannot deadlock
536-        boolean thisFirst = sheetId.compareTo(toSheetId) < 0;
537-        Sheet first = sheets.findForUpdate(thisFirst ? sheetId : toSheetId).orElse(null);
538-        Sheet second = sheets.findForUpdate(thisFirst ? toSheetId : sheetId).orElse(null);
539-        Sheet here = thisFirst ? first : second;
540-        Sheet there = thisFirst ? second : first;
541-        if (here == null) throw new SheetNotFoundException();
542-        Person person = people.findByIdAndSheetId(id, sheetId).orElseThrow(PersonNotFoundException::new);
543-        if (settings.roleOf(sheetId, user) != Role.STEWARD || person.isRetired() || there == null
544-                || there.isArchived()) {
545-            throw new PersonTransferRefusedException();
546-        }
547-        // one there of their name or an alias, as names are compared, is who they are merged into
548-        Set<Person> matching = new LinkedHashSet<>();
549-        for (String name : person.namesAndAliases()) people.findByNameOrAlias(toSheetId, name).ifPresent(matching::add);
550-        if (matching.size() > 1) throw new PersonTransferRefusedException();
551-        Person into = matching.stream().findFirst().orElse(null);
552-        if (into != null && into.isRetired()) throw new PersonTransferRefusedException();
553-        if (into == null && person.getContact() != null
554-                && people.findBySheetIdAndContact(toSheetId, person.getContact()).isPresent()) {
555-            throw new PersonTransferRefusedException();
556-        }
557-        RollupService.Snapshot beforeHere = rollup.snapshot(sheetId);
558-        RollupService.Snapshot beforeThere = rollup.snapshot(toSheetId);
559-
560-        // what ties them to this sheet is dropped
561-        patrons.deleteAll(patrons.findBySheetIdOrderByIdAsc(sheetId).stream()
562-                .filter(p -> p.getPersonId().equals(id) || p.getPatronId().equals(id)).toList());
563-        patrons.flush();
564-        poolMembers.deleteAll(poolMembers.findBySheetIdOrderByIdAsc(sheetId).stream()
565-                .filter(m -> id.equals(m.getPersonId())).toList());
566-        poolMembers.flush();
567-        watches.deleteAll(watches.findByPersonIdOrderByIdAsc(id));
568-        watches.flush();
569-
570-        // they, their statements and their claims arrive on the other sheet
571-        List<Claim> moving = claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, id);
572-        String name = person.getName();
573-        List<String> names = into != null ? leave(person, into) : List.of();
574-        person.transferTo(toSheetId);
575-        person.setPosition(people.maxPosition(toSheetId) + 1);
576-        Person saved = saveUnique(person);
577-        List<Statement> theirStatements = statements.findBySheetIdAndPersonIdOrderByIdAsc(sheetId, id);
578-        for (Statement s : theirStatements) s.moveTo(toSheetId, id);
579-        statements.saveAllAndFlush(theirStatements);
580-        claimService.receive(there, moving);
581-        claimService.keepTags(toSheetId, saved.getTags());
582-
583-        audit.recordOnCommit("PERSON_TRANSFERRED sheet=" + sheetId + " by=" + user.strip()
584-                + " name=" + name + " to=" + toSheetId);
585-        rollup.recordChanges(sheetId, user, beforeHere);
586-        audit.recordOnCommit("PERSON_TRANSFERRED sheet=" + toSheetId + " by=" + user.strip()
587-                + " name=" + name + " from=" + sheetId);
588-        if (into != null) {
589-            Person merged = absorb(toSheetId, saved, into, names);
590-            audit.recordOnCommit("PERSON_MERGED sheet=" + toSheetId + " by=" + user.strip()
591-                    + " from=" + name + " into=" + merged.getName());
592-        }

